<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeNameVO;

trait ThemeNameAttributeHolder
{
    protected ThemeNameVO|string|null $name = null;
    protected bool $nameAssigned = false;

    public function getNameOrDefault(ThemeNameVO $name): ThemeNameVO
    {
        if ($this->nameAssigned) {
            \assert(null !== $this->name);
            return ThemeNameVO::from($this->name);
        } else {
            return $name;
        }
    }
    public function name(ThemeNameVO|string $name): static
    {
        $this->name = $name;
        $this->nameAssigned = true;
        return $this;
    }
    public function getName(): ?string
    {
        return $this->name instanceof ThemeNameVO ? $this->name->value() : $this->name;
    }
    public function isNameAssigned(): bool
    {
        return $this->nameAssigned;
    }
    public function writeNameTo(mixed $att): void
    {
        if ($this->nameAssigned) {
            \assert(null !== $this->name);
            $att->name($this->name);
        }
    }
    public function readNameFrom(mixed $att): void
    {
        if ($att->isNameAssigned()) {
            $name = $att->getName();
            \assert(null !== $name);
            $this->name($name);
        }
    }
    public function unsetName(): static
    {
        $this->nameAssigned = false;
        return $this;
    }
    protected function withDefaultName(): void
    {
    }
    protected function withAssertedNameRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->nameAssigned = $this->nameAssigned) {
            $value->name = ThemeNameVO::tryFrom($this->name, $errorsList);
        }
    }
}
